SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY id),'[]'::jsonb) FROM (
    SELECT id,corp_id,connection_epoch,status,connected_at,disconnected_at,grace_expires_at
    FROM runner_nodes WHERE corp_id='00000000-0000-4000-8000-000000000001'::uuid ORDER BY id) n;

SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY id),'[]'::jsonb) FROM (
