    FROM runner_nodes WHERE corp_id='00000000-0000-4000-8000-000000000001'::uuid ORDER BY id) n;

SELECT coalesce(jsonb_agg(to_jsonb(e) ORDER BY seq),'[]'::jsonb) FROM (
    SELECT seq,type,aggregate_type,aggregate_id,correlation_id,created_at,payload FROM events
    WHERE corp_id='00000000-0000-4000-8000-000000000001'::uuid AND seq>27 ORDER BY seq) e;
